+type councilReview struct {
+	Reviewer   string             `json:"reviewer"`
+	Verdict    string             `json:"verdict"`
+	Objections []councilObjection `json:"objections,omitempty"`

+type councilObjection struct {
+	Edit     objectionEdit `json:"edit"`
+	Problem  string        `json:"problem"`
+	Severity string        `json:"severity,omitempty"`
+}
+
+// Index: 1-based into the plan's edits; 0 = plan-wide. Raw: the reviewer's own token.
+type objectionEdit struct {
+	Index int
+	Raw   json.RawMessage
+}
+
+// Never returns an error, by design: this field must not be able to cost a review.
+func (e *objectionEdit) UnmarshalJSON(b []byte) error {
+	e.Raw = append(json.RawMessage(nil), b...)
+	e.Index = 0
+	var num json.Number
+	if err := json.Unmarshal(b, &num); err == nil {
+		if f, ferr := num.Float64(); ferr == nil { e.Index = int(f) }
+		return nil
+	}
+	var s string
+	if err := json.Unmarshal(b, &s); err == nil {
+		if n, aerr := strconv.Atoi(strings.TrimSpace(s)); aerr == nil { e.Index = n }
+	}
+	return nil
+}
+func (e objectionEdit) MarshalJSON() ([]byte, error) {
+	if len(e.Raw) > 0 { return e.Raw, nil }
+	return json.Marshal(e.Index)
+}

+// Sibling of salvageTruncatedReview: the document is COMPLETE, so there is nothing
+// to repair; decode field by field and keep what decodes. Reviewer/verdict strict
+// (load-bearing), the rest best-effort. ok=false unless a RECOGNISED verdict returns.
+func salvageMistypedReview(rb []byte) (councilReview, bool) {
+	var fields map[string]json.RawMessage
+	if err := json.Unmarshal(rb, &fields); err != nil { return councilReview{}, false }
+	var rv councilReview
+	var verdict string
+	if err := json.Unmarshal(fields["verdict"], &verdict); err != nil { return rv, false }
+	rv.Verdict = strings.ToLower(strings.TrimSpace(verdict))
+	if !councilVerdicts[rv.Verdict] { return rv, false }
+	_ = json.Unmarshal(fields["reviewer"], &rv.Reviewer)
+	_ = json.Unmarshal(fields["objections"], &rv.Objections)
+	_ = json.Unmarshal(fields["missing"], &rv.Missing)
+	_ = json.Unmarshal(fields["notes"], &rv.Notes)
+	return rv, true
+}

